package com.cpf.batch.agent; import com.cpf.batch.api.*; import com.cpf.batch.runtime.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.boot.context.properties.EnableConfigurationProperties; import org.springframework.context.annotation.*;
@SpringBootApplication(scanBasePackages="com.cpf.batch.agent") @EnableConfigurationProperties(AgentProperties.class) @Import(RuntimeCommonConfiguration.class) public class BatchHostAgentApplication { public static void main(String[]a){SpringApplication.run(BatchHostAgentApplication.class,a);} @Bean RuntimeRegistration runtimeRegistration(){return RuntimeIdentityFactory.fromEnvironment(RuntimeRole.HOST_AGENT,"cpf-batch-host-agent",8184);} @Bean ApprovedCommandCatalog approvedCommandCatalog(){return new ApprovedCommandCatalog();} }
